import { BooleanColumn, StringColumn, ChoiceColumn } from '@servicenow/sdk/core'
import { ActionDefinition, FlowObject } from '@servicenow/sdk/automation'

export const fl_action_flow_object = ActionDefinition({
    $id: Now.ID['action-flow-object'],
    name: 'fl-action-flow-object',
    annotation: 'Test action with FlowObject',
    description: 'Demonstrates FlowObject usage',
    category: 'Testing',
    inputs: {
        userInfo: FlowObject({
            fields: {
                firstName: StringColumn({
                    label: 'First Name',
                    mandatory: true,
                    maxLength: 100,
                }),
                lastName: StringColumn({
                    label: 'Last Name',
                    mandatory: true,
                    maxLength: 100,
                }),
                active: BooleanColumn({
                    label: 'Is Active',
                }),
            },
            label: 'User Information',
            mandatory: true,
        }),
    },
    outputs: {
        success: BooleanColumn({
            label: 'Success',
            mandatory: true,
        }),
        result: FlowObject({
            fields: {
                id: StringColumn({
                    label: 'ID',
                }),
                message: StringColumn({
                    label: 'Message',
                }),
                status: ChoiceColumn({
                    label: 'Status',
                    default: 'success',
                    choices: {
                        success: {
                            label: 'Success',
                            sequence: 1,
                        },
                        failed: {
                            label: 'Failed',
                            sequence: 2,
                        },
                    },
                }),
            },
            label: 'Result',
            mandatory: true,
        }),
    },
})
